func artifactPath(storeRoot, fingerprint string) string {
	return filepath.Join(storeRoot, "objects", fingerprint[:2], fingerprint, "artifact")
}

func artifactSize(storeRoot, fingerprint string) (int64, error) {
	info, err := os.Stat(artifactPath(storeRoot, fingerprint))
	if err != nil {
		return 0, err
	}
	return info.Size(), nil
