```go
func cmdAudit(args []string) int {
	args, profile, status := extractProfile(args)
	if status != 0 {
		return status
	}
	if len(args) < 1 {
		fmt.Fprintln(os.Stderr, "error: usage: buildvault audit <manifest_path> --baseline <baseline_path> [--profile <name>]")
		return 1
	}

	manifestPath := args[0]
	rest := args[1:]
	baselinePath := ""

	for i := 0; i < len(rest); i++ {
		if rest[i] == "--baseline" {
			if i+1 >= len(rest) {
				fmt.Fprintln(os.Stderr, "error: audit requires --baseline <baseline_path>")
				return 1
			}
			baselinePath = rest[i+1]
			i++
		} else if strings.HasPrefix(rest[i], "--baseline=") {
			baselinePath = rest[i][len("--baseline="):]
		} else {
			fmt.Fprintf(os.Stderr, "error: unexpected argument: %s\n", rest[i])
			return 1
		}
	}

	if baselinePath == "" {
		fmt.Fprintln(os.Stderr, "error: audit requires --baseline <baseline_path>")
		return 1
	}

	m, dir, err := loadManifest(manifestPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	if err := validateManifest(m, dir); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	if err := applyProfile(m, profile); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	results, err := runBuild(m, dir)
	if err != nil {
		if errors.Is(err, errBuildFailed) {
			return 1
		}
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	data, err := os.ReadFile(baselinePath)
	if err != nil {
		if os.IsNotExist(err) {
			fmt.Fprintf(os.Stderr, "error: baseline not found: %s\n", baselinePath)
			return 1
		}
		fmt.Fprintf(os.Stderr, "error: invalid baseline: %v\n", err)
		return 1
	}

	type baselineTarget struct {
		Fingerprint string `json:"fingerprint"`
		OutputHash  string `json:"output_hash"`
	}
	var baseline struct {
		ChainHash *string                    `json:"chain_hash,omitempty"`
		Targets   map[string]baselineTarget  `json:"targets"`
	}
	if err := json.Unmarshal(data, &baseline); err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid baseline: %v\n", err)
		return 1
	}

	chainHash := computeChainHash(results)

	type extraJSON struct {
		Name        string `json:"name"`
		Fingerprint string `json:"fingerprint"`
		OutputHash  string `json:"output_hash"`
	}
	type targetJSON struct {
		Name                string `json:"name"`
		BaselineFingerprint string `json:"baseline_fingerprint"`
		CurrentFingerprint  string `json:"current_fingerprint"`
		FingerprintMatch    bool   `json:"fingerprint_match"`
		BaselineOutputHash  string `json:"baseline_output_hash"`
		CurrentOutputHash   string `json:"current_output_hash"`
		OutputMatch         bool   `json:"output_match"`
	}

	currentNames := make(map[string]bool, len(results))
	resultsByName := make(map[string]buildResult, len(results))
	for _, r := range results {
		currentNames[r.Target.Name] = true
		resultsByName[r.Target.Name] = r
	}

	extraInBaseline := make([]extraJSON, 0)
	for name, entry := range baseline.Targets {
		if !currentNames[name] {
			extraInBaseline = append(extraInBaseline, extraJSON{Name: name, Fingerprint: entry.Fingerprint, OutputHash: entry.OutputHash})
		}
	}
	sort.Slice(extraInBaseline, func(i, j int) bool { return extraInBaseline[i].Name < extraInBaseline[j].Name })

	extraInCurrent := make([]extraJSON, 0)
	for _, r := range results {
		if _, ok := baseline.Targets[r.Target.Name]; !ok {
			extraInCurrent = append(extraInCurrent, extraJSON{Name: r.Target.Name, Fingerprint: r.Fingerprint, OutputHash: r.OutputHash})
		}
	}
	sort.Slice(extraInCurrent, func(i, j int) bool { return extraInCurrent[i].Name < extraInCurrent[j].Name })

	targets := make([]targetJSON, 0, len(results))
	allCommonMatch := true
	for _, r := range results {
		entry, ok := baseline.Targets[r.Target.Name]
		if !ok {
			continue
		}
		fpMatch := entry.Fingerprint == r.Fingerprint
		outMatch := entry.OutputHash == r.OutputHash
		if !fpMatch || !outMatch {
			allCommonMatch = false
		}
		targets = append(targets, targetJSON{
			Name:                r.Target.Name,
			BaselineFingerprint: entry.Fingerprint,
			CurrentFingerprint:  r.Fingerprint,
			FingerprintMatch:    fpMatch,
			BaselineOutputHash:  entry.OutputHash,
			CurrentOutputHash:   r.OutputHash,
			OutputMatch:         outMatch,
		})
	}

	hasExtra := len(extraInBaseline) > 0 || len(extraInCurrent) > 0
	matches := allCommonMatch && !hasExtra

	type output struct {
		Matches         bool         `json:"matches"`
		ChainHash       string       `json:"chain_hash"`
		ChainMatch      *bool        `json:"chain_match,omitempty"`
		ExtraInBaseline []extraJSON  `json:"extra_in_baseline"`
		ExtraInCurrent  []extraJSON  `json:"extra_in_current"`
		Targets         []targetJSON `json:"targets"`
	}

	out := output{
		Matches:         matches,
		ChainHash:       chainHash,
		ExtraInBaseline: extraInBaseline,
		ExtraInCurrent:  extraInCurrent,
		Targets:         targets,
	}
	if baseline.ChainHash != nil {
		chainMatch := *baseline.ChainHash == chainHash
		out.ChainMatch = &chainMatch
		if !chainMatch {
			matches = false
		}
	}
	out.Matches = matches

	printJSON(out)
	return 0
}
```

