		cachedHashes[r.Target.Name] = r.OutputHash
		size, err := artifactSize(m.StoreRoot, r.Fingerprint)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: cached artifact missing for target %s: %v\n", r.Target.Name, err)
			return 1
		}
		cachedSizes[r.Target.Name] = size
	}

	fmt.Fprintln(os.Stderr, "[verify] rebuilding from clean state")
	if err := clearStoreObjects(m.StoreRoot); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	freshResults, err := runBuild(m, dir)
	if err != nil {
		if errors.Is(err, errBuildFailed) {
			return 1
		}
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	freshHashes := make(map[string]string, len(freshResults))
	freshSizes := make(map[string]int64, len(freshResults))
	for _, r := range freshResults {
		freshHashes[r.Target.Name] = r.OutputHash
		size, err := artifactSize(m.StoreRoot, r.Fingerprint)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: fresh artifact missing for target %s: %v\n", r.Target.Name, err)
			return 1
		}
		freshSizes[r.Target.Name] = size
	}

	type targetJSON struct {
		Name         string `json:"name"`
		CachedHash   string `json:"cached_hash"`
		FreshHash    string `json:"fresh_hash"`
		CachedSize   int64  `json:"cached_size"`
		FreshSize    int64  `json:"fresh_size"`
		Reproducible bool   `json:"reproducible"`
	}

	targets := make([]targetJSON, 0, len(freshResults))
	reproducible := true
	fingerprintStable := true
	for _, r := range freshResults {
		cached := cachedByTarget[r.Target.Name]
		cachedHash := cachedHashes[r.Target.Name]
		freshHash := freshHashes[r.Target.Name]
		ok := cachedHash == freshHash
		if !ok {
			reproducible = false
		}
		if cached.Fingerprint != r.Fingerprint {
			fingerprintStable = false
		}
		targets = append(targets, targetJSON{
			Name:         r.Target.Name,
			CachedHash:   cachedHash,
			FreshHash:    freshHash,
			CachedSize:   cachedSizes[r.Target.Name],
			FreshSize:    freshSizes[r.Target.Name],
			Reproducible: ok,
		})
	}

	chainHash := computeChainHash(freshResults)

	printJSON(struct {
		Reproducible      bool         `json:"reproducible"`
		FingerprintStable bool         `json:"fingerprint_stable"`
		Targets           []targetJSON `json:"targets"`
		ChainHash         string       `json:"chain_hash"`
	}{
		Reproducible:      reproducible,
		FingerprintStable: fingerprintStable,
		Targets:           targets,
		ChainHash:         chainHash,
	})
	return 0
}
